    "description": "2026年09月20日 从苍穹星座到地面终端，从交通应急、智慧城市到田间生产、远洋航行，近年来，我国北斗卫星导航系统为经济社会发展注入新动能。 以“同世界·共北斗——赋能全球”为主题的第五届北斗规模应用国际峰会近日在湖南株洲举行。自2021年首届峰会举办以来，北斗的市场辐射力持续增强、产业支撑力不断夯实、国际影响力日益深远。 性能服务提升 今年7月，北斗系统完成全部卫星在轨迭代升级。“形成全国实时厘米级位置服务能力，全球覆盖、快速收敛的…",
    "content": "2026年09月20日 从苍穹星座到地面终端，从交通应急、智慧城市到田间生产、远洋航行，近年来，我国北斗卫星导航系统为经济社会发展注入新动能。 以“同世界·共北斗——赋能全球”为主题的第五届北斗规模应用国际峰会近日在湖南株洲举行。自2021年首届峰会举办以来，北斗的市场辐射力持续增强、产业支撑力不断夯实、国际影响力日益深远。 性能服务提升 今年7月，北斗系统完成全部卫星在轨迭代升级。“形成全国实时厘米级位置服务能力，全球覆盖、快速收敛的高精度定位服务能力，10亿级终端接入和亿级大众用户、百万级行业用户稳定在线的保障…"
