    "content": "2026年09月20日 “习近平主席强调，金砖国家要做推动文明互鉴的先锋。金砖电视台非洲频道愿不断将人文交流愿景转化为具体实践，为促进金砖国家民众相知相亲贡献力量。”金砖电视台非洲频道负责人阿扬达·霍洛日前在接受本报记者采访时表示。 “金砖合作机制自成立以来，始终秉持开放包容、合作共赢精神，已成为当今世界最具影响力的新兴市场和发展中国家合作平台。”霍洛说，中国推动金砖务实合作朝着更高质量方向发展，不断增强金砖合作机制的韧性与活力，“中国是金砖合作的参与者、建设者、推动者，既在基础设施、经贸投资、数字经济等领域持续深…"
