    "description": "2026年09月20日 文人墨客，行至三峡必有诗。近日，2026世界大河诗会在重庆举行。夜泊白帝城外、瞿塘峡口，中外嘉宾船行长江，在“中华诗城”重庆市奉节县上演“赛诗会”。 “故里春方启，此地秋已临。”澳大利亚著名诗人，蒙特利尔国际诗歌奖、卡迪夫国际诗歌奖双料得主马克·特雷迪尼克应景的起句赢得阵阵掌声。他说，特意仿杜甫作品写此诗，诗名《江秋》，致敬先贤——“沿着河滨，荔枝红果”“芦荻丛里，褐雉出没”“近有长桥，横亘晓色，远山吐蒙蒙细雨”…",
    "content": "2026年09月20日 文人墨客，行至三峡必有诗。近日，2026世界大河诗会在重庆举行。夜泊白帝城外、瞿塘峡口，中外嘉宾船行长江，在“中华诗城”重庆市奉节县上演“赛诗会”。 “故里春方启，此地秋已临。”澳大利亚著名诗人，蒙特利尔国际诗歌奖、卡迪夫国际诗歌奖双料得主马克·特雷迪尼克应景的起句赢得阵阵掌声。他说，特意仿杜甫作品写此诗，诗名《江秋》，致敬先贤——“沿着河滨，荔枝红果”“芦荻丛里，褐雉出没”“近有长桥，横亘晓色，远山吐蒙蒙细雨”……特雷迪尼克的诗中，满是长江生态胜景、宜居美好环境，道尽此行的生动见闻与真切感…"
