    "content": "2026年09月20日 第二十届亚运会开幕式现场。 王伟伟摄（影像中国） \"> 中国体育代表团入场。 本报记者 安博文摄 \"> 9月19日，第二十届亚洲运动会开幕式在日本名古屋市瑞穗公园田径场举行。亚洲45个国家和地区的代表团成员齐聚一堂，亚洲体育盛会正式启幕。 主体育场中央设心形舞台，起伏的光带模拟心跳节律，由浅入深的色块从舞台向外铺展，象征亚洲不同地域人们的情感在同一时空汇聚。 山海相连、人文相亲，亚洲人民对盛会充满期盼。杭州一别，此番再聚，亚运会既是展示竞技之美的赛场，也是友好交流的平台。正如亚奥理事会主席焦…"
