    "description": "2026年09月20日 亚运会开幕式后，更多项目将进入比赛日，首金也将诞生。 首金之争向来是亚运会开幕后的焦点。9月20日，铁人三项男子个人赛、公路自行车女子个人计时赛、现代五项女子个人及团体赛等多项决赛集中开赛，赛会首金将从中诞生。自2002年釜山亚运会以来，中国体育代表团已连续6届亚运会赢得首金。 开幕后的首个比赛日，游泳项目有望成为中国队的夺金大项。游泳比赛在东京举办，20日将产生7枚金牌，中国队均有夺金实力。第五次参加亚运会的汪…",
    "content": "2026年09月20日 亚运会开幕式后，更多项目将进入比赛日，首金也将诞生。 首金之争向来是亚运会开幕后的焦点。9月20日，铁人三项男子个人赛、公路自行车女子个人计时赛、现代五项女子个人及团体赛等多项决赛集中开赛，赛会首金将从中诞生。自2002年釜山亚运会以来，中国体育代表团已连续6届亚运会赢得首金。 开幕后的首个比赛日，游泳项目有望成为中国队的夺金大项。游泳比赛在东京举办，20日将产生7枚金牌，中国队均有夺金实力。第五次参加亚运会的汪顺、奥运冠军潘展乐，以及徐嘉余、李冰洁、唐钱婷都将开启卫冕之旅。 在中国体育代表…"
