    "description": "2026年09月20日 位于广东汕头小公园开埠区海平路的一处老骑楼里，工作人员打开锈痕斑驳的铁盒，里面整整齐齐码着几十封泛黄的信笺，落款多是“吾妻安康”“见字如面”——这是电影《给阿嬷的情书》里让许多观众落泪的实物原型。 银信跨海，一头连着故土炊烟，一头牵着番客艰辛。当年靠一纸银信养家糊口，如今以侨为桥引资、引智、引货、引文化，海外中华儿女与家乡的“连心桥”越建越宽。 作为重要侨乡，广东省近年来持续做好新时代“侨”的文章，成立侨助经济高…",
    "content": "2026年09月20日 位于广东汕头小公园开埠区海平路的一处老骑楼里，工作人员打开锈痕斑驳的铁盒，里面整整齐齐码着几十封泛黄的信笺，落款多是“吾妻安康”“见字如面”——这是电影《给阿嬷的情书》里让许多观众落泪的实物原型。 银信跨海，一头连着故土炊烟，一头牵着番客艰辛。当年靠一纸银信养家糊口，如今以侨为桥引资、引智、引货、引文化，海外中华儿女与家乡的“连心桥”越建越宽。 作为重要侨乡，广东省近年来持续做好新时代“侨”的文章，成立侨助经济高质量发展专班，实施“侨助广东高质量发展行动”“汇侨智&nbsp;&nbsp;聚侨…"
