    "author": "",
    "description": "2026年09月20日 当千年笔墨跨越时空展现在今人面前，一个值得深思的命题随之浮现：中国书画“典则”何以确立？又该如何传承发展？近日，“典则：唐宋书画展”首期在故宫博物院文华殿启幕，汇聚一批珍品，如隋代展子虔《游春图》卷、唐代阎立本《步辇图》卷、杜牧行书《张好好诗》卷等，系统梳理魏晋南北朝至两宋时期的书画演进脉络，为人们读懂“典则”提供诸多启示。 “典则”语出《尚书》：“有典有则，贻厥子孙”，本指先王传续后世的典章法度。唐人窦蒙《述书…",
    "content": "2026年09月20日 当千年笔墨跨越时空展现在今人面前，一个值得深思的命题随之浮现：中国书画“典则”何以确立？又该如何传承发展？近日，“典则：唐宋书画展”首期在故宫博物院文华殿启幕，汇聚一批珍品，如隋代展子虔《游春图》卷、唐代阎立本《步辇图》卷、杜牧行书《张好好诗》卷等，系统梳理魏晋南北朝至两宋时期的书画演进脉络，为人们读懂“典则”提供诸多启示。 “典则”语出《尚书》：“有典有则，贻厥子孙”，本指先王传续后世的典章法度。唐人窦蒙《述书赋语例字格》从艺术维度加以阐释：“从师约法曰典，可以传授曰则。”其意为：“典”是…"
