    "author": "",
    "description": "2026年09月20日 北宋绍圣二年（公元1095年），李清照的父亲李格非遍游洛阳，写下一部《洛阳名园记》。他笔下的19座名园中，有一座颇为特别，其“卑小不可与他园班”，却因园主的人格和志趣为时人所追慕。它就是司马光的独乐园。司马光曾为它创作《独乐园记》《独乐园七题》等名篇，苏轼、苏辙、黄庭坚等文人都曾为它赋诗，明代“吴门四家”中的文徵明、仇英等曾为它作画，后世不少人仿其造园，形成独特的“独乐园现象”。 在历代绘写独乐园的作品中，仇英的…",
    "content": "2026年09月20日 扫描二维码，观看相关视频。 \"> 北宋绍圣二年（公元1095年），李清照的父亲李格非遍游洛阳，写下一部《洛阳名园记》。他笔下的19座名园中，有一座颇为特别，其“卑小不可与他园班”，却因园主的人格和志趣为时人所追慕。它就是司马光的独乐园。司马光曾为它创作《独乐园记》《独乐园七题》等名篇，苏轼、苏辙、黄庭坚等文人都曾为它赋诗，明代“吴门四家”中的文徵明、仇英等曾为它作画，后世不少人仿其造园，形成独特的“独乐园现象”。 在历代绘写独乐园的作品中，仇英的《独乐园图》（局部见图）为后世想象这座北宋名园…"
