    "description": "9月18日，“活力中国调研行”采访团走进湖北宜昌秭归县郭家坝镇烟灯堡村，几位无人机飞手正操控着无人机，将一筐筐橙子从柑橘园里吊装运至山下。据了解，秭归县已集聚专业飞手2700多人，累计吊运脐橙超70万吨。",
