    "author": "澎湃新闻记者 高丹",
    "description": "在《云雀叫天录》中，谭卓饰演沈玉儿。这部作品取材于京剧大师谭鑫培的生平，沈玉儿角色原型为京剧大师谭鑫培的第一位夫人侯玉儿，谭家后人称她为高祖，评价她是“大善人”。这个人物成为谭卓理解沈玉儿的重要参照。 初读剧本时，正是人物身上这种与家族命运相连又有着自身能动性的特质，吸引谭卓接下了这个角色。近日，谭卓接受澎湃新闻专访，聊起读到剧本时的兴奋、对沈玉儿的偏爱，以及和张一山从少年夫妻演到老年相伴的感受。她说，沈玉儿是她塑造过的人物里最喜欢的女…",
