    "content": "这些年去过30多个国家，钱包里进进出出过各种纸币和硬币。最近在吉尔吉斯斯坦机场买三明治，收银员找给我一枚硬币。低头一看，我愣了一下：3 SOM。 如果在中国，商家找给你一枚3块钱的硬币，你大概会怀疑是假钱。但这枚3索姆是真的，而且至今仍是吉尔吉斯斯坦的法定流通货币。这种面额现在已经很少见。今天世界上仍把“3个主币单位”作为流通货币面额的国家屈指可数，吉尔吉斯斯坦和塔吉克斯坦就是两个典型。 吉尔吉斯斯坦的3索姆硬币 为什么我们熟悉的是1、2、5、10，却有人偏偏喜欢3？更有意思的是，吉尔吉斯斯坦的3索姆还不是一枚从苏…"
