    "content": "初秋时节，故宫文华殿又一次迎来文博爱好者的热切聚焦。历经两年多筹备的“典则：唐宋书画展”亮相以来，吸引上万名观众慕名而至，奔赴一场跨越千年的精神对话。 这场展览共展出书画文物107件，有24件为近三十年来首次展出，另有部分晋唐写经、五代寺观壁画此前亦较少面世。展览自9月1日至11月1日开放，按朝代顺序分为两期，第一期主题为唐、五代书画，第二期主题为两宋书画。 一套“行业标准” 唐之法度，宋之意韵，共同构筑了中国传统书画的精神内核。理解唐宋笔墨乃至读懂中国传统书画，就要从展览的主题“典则”说起。 “从师约法曰典，可以…"
