    "content": "再过不久，上海今年最出圈的“狗狗”——静安苏河湾万象天地的西高地犬绿雕，将换上“秋装”。项目负责人冯瑞透露，换装预计10月中旬进行，届时“花背心”将更新为紫菀等菊科植物，具体方案还在制定中。 这尊高达5.2米的绿雕，于2026年4月在上海国际花卉节亮相，之后迅速成为城市新晋IP。它神情憨厚、毛发飘逸，身穿花背心，一副炸毛模样，被网友亲切唤作“潦草小狗”。 从春天火到秋天的“潦草小狗”，10月将继续展出并联动上海菊花展再换新装。澎湃新闻记者 张呈君 陈悦 编辑 何羽茜(03:01) “小狗”营业半年来，吸引无数游客打…"
