    "author": "澎湃新闻记者 韩雨亭 发自福建宁德",
    "description": "坂中村位于福建省宁德市古田县翠屏湖畔的吉巷乡。一场大雨后，村庄空气清新，远山薄雾尚未散尽。菇棚顺着山势散落，蓝色的光伏板在阳光下格外亮眼。 坂中村村民彭仁胜寡言少语，是当地知名的菇农，有40多年的银耳种植技术和经验。他在坂中村的几座钢架光伏菇棚依山错落而建，棚内高大宽敞，通风透光，安装有自动化喷淋系统。 在古田县，像彭仁胜这样的银耳种植大户随处可见。 如今，古田已成为名副其实的“中国食用菌之都”，是全球人工袋料/袋栽银耳的重要发源地和中…",
    "content": "坂中村位于福建省宁德市古田县翠屏湖畔的吉巷乡。一场大雨后，村庄空气清新，远山薄雾尚未散尽。菇棚顺着山势散落，蓝色的光伏板在阳光下格外亮眼。 坂中村村民彭仁胜寡言少语，是当地知名的菇农，有40多年的银耳种植技术和经验。他在坂中村的几座钢架光伏菇棚依山错落而建，棚内高大宽敞，通风透光，安装有自动化喷淋系统。 在古田县，像彭仁胜这样的银耳种植大户随处可见。 如今，古田已成为名副其实的“中国食用菌之都”，是全球人工袋料/袋栽银耳的重要发源地和中国最大的银耳商品化生产基地。银耳产量占全国90%以上，占全球同类商品生产份额约九…"
