    "content": "新华社利雅得9月19日电（记者罗晨）沙特阿拉伯主导的多国联军发言人图尔基·马利基19日说，沙特防空部队当天凌晨拦截了一枚也门胡塞武装向沙特首都利雅得发射的弹道导弹。 马利基当晚在社交媒体上发表声明说，也门胡塞武装持续升级行动，企图袭击利雅得的平民和民用设施。 他补充说，胡塞武装还企图袭击拜什、塔伊夫、法拉桑和延布等沙特城市的平民和民用设施，但均已被挫败。 声明强烈谴责胡塞武装的袭击，强调多国联军有权依据国际人道法采取适当措施，以遏制胡塞武装的行径。 利雅得19日两次传出爆炸声，一次在当天凌晨，另一次在当天上午。位于…"
