    "content": "“回流药”，指的是通过医保报销开出的药，被药贩子低价回收、非法转手再重新流入市场的药品。在网络售药平台，不少在售的药品价格远低于实体门店，实际暗含“回流药”风险。 广州医保部门依托“药品追溯码”大数据模型预警，对可疑人员就医轨迹深入研判，经过缜密摸排、连续蹲守，联合公安机关开展专项行动，成功打掉一个收药倒药的犯罪团伙。在一处仓库内，医保和公安发现，30多摄氏度的闷热潮湿环境中，本该冷链保存的药品被常温零散摆放。嫌疑人发货时，却会采用泡沫箱、铝箔纸等，伪装成药品冷链保存的样子，掩盖药品脱离冷链甚至可能变质的事实。 据…"
