    "description": "中新社西安9月19日电 (记者 张一辰)夜幕低垂，华灯点亮千年大雁塔，塔身光影流转。大雁塔北广场人头攒动，市民与游客在细雨中共赴一场音乐之约。19日晚间，西安交响乐团大雁塔户外公演如期上演。古塔之下，气势磅礴的交响乐与高亢豪迈的秦腔完成了一场中西文化的相遇。",
    "content": "中新社西安9月19日电 (记者 张一辰)夜幕低垂，华灯点亮千年大雁塔，塔身光影流转。大雁塔北广场人头攒动，市民与游客在细雨中共赴一场音乐之约。19日晚间，西安交响乐团大雁塔户外公演如期上演。古塔之下，气势磅礴的交响乐与高亢豪迈的秦腔完成了一场中西文化的相遇。"
