    "author": "黄扬,马欣然",
    "description": "新华社台北9月19日电（记者黄扬、马欣然）《云宫迅音》前奏在可容纳上千人的信义剧场“Legacy MAX”奏响时，场内顷刻间爆发出掌声与欢呼。19日晚，《黑神话：悟空》全球音乐会台北站正式奏响。这是该音乐会首次登陆台湾。 “这音乐一响，感觉一下热血起来，随时要变成悟空，拿着金箍棒开打了！”来自台湾的游戏主播“阿瑞斯”在现场对记者说。 这场音乐会基于3A游戏《黑神话：悟空》打造，由两岸演奏团队、音乐人及美国好莱坞电影乐团合作呈现。音乐会精…",
    "content": "新华社台北9月19日电（记者黄扬、马欣然）《云宫迅音》前奏在可容纳上千人的信义剧场“Legacy MAX”奏响时，场内顷刻间爆发出掌声与欢呼。19日晚，《黑神话：悟空》全球音乐会台北站正式奏响。这是该音乐会首次登陆台湾。 “这音乐一响，感觉一下热血起来，随时要变成悟空，拿着金箍棒开打了！”来自台湾的游戏主播“阿瑞斯”在现场对记者说。 这场音乐会基于3A游戏《黑神话：悟空》打造，由两岸演奏团队、音乐人及美国好莱坞电影乐团合作呈现。音乐会精选《黄风起兮》《看见》《未竟》等17首游戏原声，以及《云宫迅音》《敢问路在何方》…"
