    "content": "新华社武汉9月19日电（记者乐文婉）第十二届“金飞燕”海峡两岸微电影微视频大赛19日晚在湖北武汉谭鑫培戏楼落幕。近50位台湾青年与武汉高校师生以光影为媒交流互鉴，推动两岸影视文化合作走深走实。 据组委会介绍，本届赛事共收到近500部参赛作品，其中237部来自台湾，体裁覆盖微电影、微短剧及AI漫剧等，题材涵盖两岸市井烟火、青年成长、亲情乡愁、文化传承等。经两岸专家评审，选出61部入围作品。 大陆作品《一脉烟火》从一道家乡菜出发，寻找一段家族记忆，展示两岸同胞共同的文化根脉和情感归属，斩获“金飞燕”奖。大陆作品《日落后…"
