    "content": "新华社万象9月19日电（周娜）中老“和平列车-2026”医疗队16日至18日在老挝万象市、巴色市、沙湾拿吉省、阿速坡省多地，同步开展学术交流与医疗服务活动。 学术交流活动聚焦老挝常见病、多发病及卫勤保障现实需求，由肖颖彬、黎檀实、孙天胜等国内知名医学专家，重点围绕心脏外科急救、大规模伤亡应急医学救援、退变性脊柱侧弯治疗等进行专题授课，分享中国军医在灾害医学救援和基层实战保障中的经验，推动两军卫勤领域深入交流合作。 在万象医疗服务点，医疗队同步展开临床诊疗工作。针对一例耳病疑难病例，中方专家连线国内开展远程视频会诊，…"
