    "pub_date": "2026-09-19 22:35:17",
    "author": "",
    "description": "中新社成都9月19日电 (记者 安源 刘忠俊 岳依桐)9月19日凌晨，四川攀枝花市盐边县格萨拉乡支六河村石家沟隧道附近突发泥石流，已致5人失联。记者19日晚从四川省应急管理厅获悉，搜救工作仍在紧张进行，初步了解，5名失联人员为当地在建高速公路项目施工人员。",
    "content": "中新社成都9月19日电 (记者 安源 刘忠俊 岳依桐)9月19日凌晨，四川攀枝花市盐边县格萨拉乡支六河村石家沟隧道附近突发泥石流，已致5人失联。记者19日晚从四川省应急管理厅获悉，搜救工作仍在紧张进行，初步了解，5名失联人员为当地在建高速公路项目施工人员。"
