    "pub_date": "2026-09-19 22:24:19",
    "author": "彭奕凯,王云（摄制）",
    "description": "近日，云南省麻栗坡县依托老山女子民兵排打造的全民国防教育创新实践模式，成功入选2026年新时代全民国防教育先进典型实践案例。 过去，麻栗坡县国防教育多以展板宣讲、课堂授课为主，形式相对单一，难以形成持久的感染力。2022年12月，该县组建老山女子民兵排，明确“唱红歌、讲党史、传精神、做服务”四大职能，并把红歌宣唱作为开展国防教育的切入点。队员们深挖本土红色资源，筛选打磨《小草》《十五的月亮》等经典曲目，并针对不同群体定制宣唱版本，让红歌…",
    "content": "近日，云南省麻栗坡县依托老山女子民兵排打造的全民国防教育创新实践模式，成功入选2026年新时代全民国防教育先进典型实践案例。 过去，麻栗坡县国防教育多以展板宣讲、课堂授课为主，形式相对单一，难以形成持久的感染力。2022年12月，该县组建老山女子民兵排，明确“唱红歌、讲党史、传精神、做服务”四大职能，并把红歌宣唱作为开展国防教育的切入点。队员们深挖本土红色资源，筛选打磨《小草》《十五的月亮》等经典曲目，并针对不同群体定制宣唱版本，让红歌跳出单纯的文艺表演范畴，成为可听、可感、可共情的“流动思政课”。 麻栗坡县将持续…"
