    "description": "新华社北京9月19日电（记者高敬）记者19日从生态环境部获悉，生态环境部等部门将形成合力，重拳整治生态环境监测机构弄虚作假问题。 日前，生态环境部联合相关部门在京召开全国深入打击生态环境监测机构弄虚作假问题部署推进会。生态环境部部长黄润秋表示，监测机构造假问题依然严重、形势依然严峻，必须始终坚持零容忍态度，重拳整治这一问题，切实守牢生态环境监测质量底线。要按照“摸清底数、集中整改、规范运行”三个阶段，部署深入打击监测机构弄虚作假问题，推…",
    "content": "新华社北京9月19日电（记者高敬）记者19日从生态环境部获悉，生态环境部等部门将形成合力，重拳整治生态环境监测机构弄虚作假问题。 日前，生态环境部联合相关部门在京召开全国深入打击生态环境监测机构弄虚作假问题部署推进会。生态环境部部长黄润秋表示，监测机构造假问题依然严重、形势依然严峻，必须始终坚持零容忍态度，重拳整治这一问题，切实守牢生态环境监测质量底线。要按照“摸清底数、集中整改、规范运行”三个阶段，部署深入打击监测机构弄虚作假问题，推动行业生态持续净化、监测行为有效规范。 生态环境部要求，要全面摸清底数，抓紧开展…"
