    "title": "第48届世界技能大赛中国代表团在上海完成集结",
    "link": "http://www.news.cn/20260919/5144ba86f09142b4a5a32e1db18cb06d/c.html",
    "pub_date": "2026-09-19 22:19:53",
    "author": "张晓洁,周蕊",
    "description": "新华社上海9月19日电（记者张晓洁、周蕊）记者从人力资源社会保障部获悉，第48届世界技能大赛中国代表团已于9月19日在上海完成集结，将奋力实现竞技成绩与精神文明双丰收。 9月22日至27日，第48届世界技能大赛将在上海举办。最新数据显示，本届世赛将有68个国家和地区的1385名选手参赛，参赛国家和地区数、参赛选手人数均创历届之最。 中国代表团中的71名参赛选手将参加全部64个项目的比赛。中国代表团将坚持以赛促学、以赛促训、以赛促评、以赛…",
    "content": "新华社上海9月19日电（记者张晓洁、周蕊）记者从人力资源社会保障部获悉，第48届世界技能大赛中国代表团已于9月19日在上海完成集结，将奋力实现竞技成绩与精神文明双丰收。 9月22日至27日，第48届世界技能大赛将在上海举办。最新数据显示，本届世赛将有68个国家和地区的1385名选手参赛，参赛国家和地区数、参赛选手人数均创历届之最。 中国代表团中的71名参赛选手将参加全部64个项目的比赛。中国代表团将坚持以赛促学、以赛促训、以赛促评、以赛促建，充分展现新时代中国技能青年过硬本领与工匠风采，推动我国技能人才队伍建设工作…"
