    "content": "新华社成都9月19日电（记者童芳）19日，“一日之计在非遗：香港非物质文化遗产与当代艺术展”在成都市美术馆揭幕，以旅客视角带观众在日常场景中探索香港非遗魅力。 图为展出的竹艺装置艺术家林嘉裕创作的《老家》（9月18日摄）。新华社发 本次展览是9月4日在成都揭幕的文化交流活动“香港周”的组成部分，由香港特区政府康乐及文化事务署主办，汇聚11项香港非遗项目与三位香港当代艺术家的创作，让传统工艺与当代艺术交汇，展现香港别具特色的人文风貌。展览亦借“香港周”的契机，设计了一个关于成都盖碗茶与龙门阵文化的陈列，开启两城之间的…"
