    "author": "何光海",
    "description": "新华社吉隆坡9月19日电（记者何光海 王嘉伟）马来西亚交通部长陆兆福19日宣布辞职。 陆兆福是在马来西亚民主行动党中央执行委员会会议结束后宣布辞职决定。此次会议旨在讨论该党对马来西亚前总理纳吉布获得有条件特赦、以居家服刑方式完成剩余刑期的回应。民主行动党是马来西亚联合政府中拥有国会席位最多的政党，陆兆福担任该党秘书长。 陆兆福说，他辞职是对这项特赦表示抗议，民主行动党其他部长不会辞职。 此前一天，马来西亚联邦直辖区特赦局宣布对纳吉布有条…",
    "content": "新华社吉隆坡9月19日电（记者何光海 王嘉伟）马来西亚交通部长陆兆福19日宣布辞职。 陆兆福是在马来西亚民主行动党中央执行委员会会议结束后宣布辞职决定。此次会议旨在讨论该党对马来西亚前总理纳吉布获得有条件特赦、以居家服刑方式完成剩余刑期的回应。民主行动党是马来西亚联合政府中拥有国会席位最多的政党，陆兆福担任该党秘书长。 陆兆福说，他辞职是对这项特赦表示抗议，民主行动党其他部长不会辞职。 此前一天，马来西亚联邦直辖区特赦局宣布对纳吉布有条件特赦，允许他以居家服刑方式完成剩余刑期。此间舆论认为，民主行动党长期以反腐败为…"
