    "content": "新华社亚的斯亚贝巴9月19日电（记者刘方强）埃塞俄比亚鲁班工坊智能楼宇技术实训基地19日在埃塞首都亚的斯亚贝巴揭牌启运。该基地将中国职业教育经验、智能楼宇技术和企业工程实践有机结合，为埃塞青年在智能建筑、节能解决方案和数字化系统等领域提供了实训平台。 中国驻埃塞俄比亚大使馆公参刘晓光在揭牌仪式上表示，今年是“中非人文交流年”。此次实训基地的设立，是践行中非人文交流理念、深化中埃塞职业教育合作的务实举措，也是鲁班工坊建设在埃塞俄比亚的进一步延伸和拓展。 天津职业技术师范大学党委书记、校长郑清春在视频致辞时说，埃塞鲁班…"
