    "description": "新华社香港9月19日电 香港海关19日公布，近日在葵涌海关大楼验货场侦破一宗历来最大海路贩运毒品案件，检获约535公斤疑似大麻花，3名怀疑涉案男子被捕。 海关根据风险评估及情报分析，拣选及检查一个从泰国抵港、报称载有保温箱的海运货柜。经查验，海关人员在货柜内发现1342个保温箱，其中364个保温箱内藏有共重约535公斤的疑似大麻花。该批疑似大麻花以真空袋包裹，并藏于保温箱当中。 跟进调查后，海关人员采取行动，于17日在旺角先后拘捕两名分…",
    "content": "新华社香港9月19日电 香港海关19日公布，近日在葵涌海关大楼验货场侦破一宗历来最大海路贩运毒品案件，检获约535公斤疑似大麻花，3名怀疑涉案男子被捕。 海关根据风险评估及情报分析，拣选及检查一个从泰国抵港、报称载有保温箱的海运货柜。经查验，海关人员在货柜内发现1342个保温箱，其中364个保温箱内藏有共重约535公斤的疑似大麻花。该批疑似大麻花以真空袋包裹，并藏于保温箱当中。 跟进调查后，海关人员采取行动，于17日在旺角先后拘捕两名分别为21岁及47岁的本地男子，以及一名44岁前来收回货物的越南籍男子。 被捕的两…"
