    "author": "",
    "description": "中新社北京9月19日电 (记者 孙自法)中国科学院空天信息创新研究院(空天院)19日向媒体通报说，其旗下齐鲁空天信息研究院(济南空天信息山东省实验室)当天集中发布三项商业航天领域重要成果，包括先进SAR(合成孔径雷达)卫星载荷、太空交通管理综合服务平台、低轨卫星轨道精密测量服务系统。",
    "content": "中新社北京9月19日电 (记者 孙自法)中国科学院空天信息创新研究院(空天院)19日向媒体通报说，其旗下齐鲁空天信息研究院(济南空天信息山东省实验室)当天集中发布三项商业航天领域重要成果，包括先进SAR(合成孔径雷达)卫星载荷、太空交通管理综合服务平台、低轨卫星轨道精密测量服务系统。"
