    "content": "9月19日晚 在名古屋瑞穗公园田径场 心形主火炬被点燃 第20届亚运会正式启幕 9月19日，火炬手室伏广志（右）、室伏重信在第20届亚洲运动会开幕式上向观众致意。新华社记者 周密 摄 四年一度的亚洲体育盛会 点火的方式或许在变 但星火承载的热血与浪漫 延绵不断 1990年9月22日，第11届亚运会开幕式在北京工人体育场举行。这是开幕式现场的主火炬塔。新华社记者 周确 摄 1990年北京亚运会 是亚运圣火第一次照亮华夏大地 也是一代人的深刻记忆 源自念青唐古拉山的纯净火种 历经一个月的接力 传遍神州大地 1990年8…"
