    "title": "校馆弦歌丨浙江大学图书馆：典籍可触 资源无界",
    "link": "http://www.news.cn/20260919/33a4ab20b7104b5295b606375f0b3ab2/c.html",
    "pub_date": "2026-09-19 21:17:58",
    "author": "刘铭翔",
    "description": "从1897年求是书院藏书室启程，跨越一百二十余载，浙江大学图书馆构建起实体与数字协同、古今文脉贯通的多元融通文献资源体系。 超700万册实体馆藏筑牢根基，800多个数据库打破时空壁垒，古籍特藏与数字平台让千年文脉触手可及。 从“镇馆之宝”南宋《资治通鉴纲目》到CADAL数字图书馆，从万部线装古籍到自研写本文献数据库——这座知识宝库正以藏筑基、以用赋能、以融提质，全方位助力人才培育、科研突破与文化传播。 记者：刘铭翔 新华社音视频部制作",
    "content": "从1897年求是书院藏书室启程，跨越一百二十余载，浙江大学图书馆构建起实体与数字协同、古今文脉贯通的多元融通文献资源体系。 超700万册实体馆藏筑牢根基，800多个数据库打破时空壁垒，古籍特藏与数字平台让千年文脉触手可及。 从“镇馆之宝”南宋《资治通鉴纲目》到CADAL数字图书馆，从万部线装古籍到自研写本文献数据库——这座知识宝库正以藏筑基、以用赋能、以融提质，全方位助力人才培育、科研突破与文化传播。 记者：刘铭翔 新华社音视频部制作"
