    "content": "新华社贝鲁特9月19日电 题：加沙废墟未冷，重磅炸弹将至 新华社记者申峰 王昊 美国媒体近日披露，美国政府正筹划向以色列提供价值达28亿美元的弹药，包括数万枚2000磅级重型航空炸弹及钻地弹头。这类重磅炸弹此前曾因可能造成惨重平民伤亡而在2024年被暂缓交付，但在政策调整后又重获放行。这也是近年来规模最大的单笔同类炸弹军售。 报道称，2000磅炸弹是西方武器库中破坏力最强的弹药之一。一枚MK-84型炸弹的杀伤范围达数百米，能破坏厚重的混凝土或金属结构，在地面留下巨大弹坑。 这笔交易的大部分款项将通过美国“外国军事融…"
