    "content": "城市更新既是民生工程，也是发展工程、文化工程。 习近平总书记高度重视历史文化保护传承，强调重视保护城市独特的历史文脉、人文地理、自然景观。 从“要像爱惜自己的生命一样保护好城市历史文化遗产”的殷殷嘱托，到“要把传统和现代有机融合在一起”的深邃思考，习近平总书记关于城市建设的一系列重要指示，指引着广大城市建设者以文化自觉，守护城市根脉。 珍爱：守护城市历史和文脉 很多来福州的人，都首选去三坊七巷走一走，触摸它在这座城市2200多年历史中的文脉印记。 沿着青石板路前行，人们领略着坊巷起于晋、成于唐宋、鼎盛于明清时期的古…"
