    "content": "新华社大马士革9月19日电（记者林建杰）据叙利亚国家通讯社19日报道，叙利亚过渡政府军队在叙东部代尔祖尔省一处驻扎点18日发生爆炸，致11名过渡政府国防部人员死亡。过渡政府国防部19日在代尔祖尔市为遇难人员举行送葬仪式。 总部设在英国的“叙利亚人权观察组织”说，爆炸发生在过渡政府国防部一座军事营地的弹药库，导致库内弹药接连爆炸，弹片在事发地点周边飞散。事发初期，救护、消防和民防人员一度难以进入现场开展救援。 本月9日，叙西北部伊德利卜省发生过类似的爆炸事件，一个用于存储武器和战争遗留物的临时仓库发生爆炸，造成14名…"
