    "author": "宋立崑,高敬,曹佩弦,鲁金博",
    "description": "新华社武汉9月19日电 题：科技兴农绘就荆楚丰收画卷 新华社记者宋立崑、高敬、曹佩弦 鱼肥鳝美，莲藕盈塘，9月的湖北，处处涌动着丰收气息。 近日，记者跟随“活力中国调研行”采访团走访了解到，湖北正持续推动农业科技创新与产业创新深度融合，形成多项核心技术，培育出一批特色优质农产品，农业产业提质增效成果丰硕。 在仙桃市张沟镇先锋村，记者来到仙桃市黄鳝农产品供应链有限公司的培苗间，只见蓝色培育箱整齐排布，一条条黄鳝幼苗在箱内缓缓游动。 “等长…",
    "content": "新华社武汉9月19日电 题：科技兴农绘就荆楚丰收画卷 新华社记者宋立崑、高敬、曹佩弦 鱼肥鳝美，莲藕盈塘，9月的湖北，处处涌动着丰收气息。 近日，记者跟随“活力中国调研行”采访团走访了解到，湖北正持续推动农业科技创新与产业创新深度融合，形成多项核心技术，培育出一批特色优质农产品，农业产业提质增效成果丰硕。 在仙桃市张沟镇先锋村，记者来到仙桃市黄鳝农产品供应链有限公司的培苗间，只见蓝色培育箱整齐排布，一条条黄鳝幼苗在箱内缓缓游动。 “等长到筷子长短，这些鳝苗就能分发到农户手里。”先锋村党总支书记朱传宝说，“过去村里黄…"
