    "content": "新华社日本名古屋9月19日电（记者王恒志、杨帆）爱知·名古屋亚运会20日将迎来开幕后首个比赛日，共产生31枚金牌，最大悬念是哪个项目将为中国代表团带来首金。而到傍晚，在东京的泳池里，中国队或将掀起夺金潮。 9月19日，中国体育代表团在开幕式上入场。新华社记者 刘磊 摄 本届亚运会首金预计在武术男子长拳、铁人三项男子个人赛、公路自行车女子个人计时赛之间产生。已经连续六届夺得赛会首金的中国队，再度蝉联的难度不小。 男子长拳是中国队优势项目，过去六届赛会两次在该项目上收获首金，但本届赛事中国队并未参加该项目；铁人三项是东…"
