    "content": "新华社北京9月19日电 伊朗媒体19日报道，伊朗一名男子被指控向以色列情报机构提供关于伊朗军事基地的情报，已被处决。 据隶属于伊朗司法部的“平衡”通讯社报道，这名男子名为侯赛因·佩达兰，曾将伊朗中部伊斯法罕省军事基地的情报提供给以色列情报和特勤局（摩萨德）以换取金钱。 报道说，佩达兰通过互联网与摩萨德建立了联系，接受相关培训，向摩萨德提供有关军事地点和人员的情报信息。2025年以色列和美国对伊朗发动的打击中，伊朗一些地点遭袭击并导致人员伤亡，佩达兰提供的信息可能发挥了部分作用。 调查人员在佩达兰的住所查获与导弹相关…"
