    "description": "9月19日18时50分，我国在太原卫星发射中心使用长征二号丁运载火箭，成功将株洲太空星际PIESAT-2 13～16星发射升空，卫星顺利进入预定轨道，发射任务取得圆满成功。新华社发（王亚鹏 摄） 新华社太原9月19日电（李国利、李宸）9月19日18时50分，我国在太原卫星发射中心使用长征二号丁运载火箭，成功将株洲太空星际PIESAT-2 13～16星发射升空，卫星顺利进入预定轨道，发射任务取得圆满成功。 这次任务是长征系列运载火箭的第6…",
    "content": "9月19日18时50分，我国在太原卫星发射中心使用长征二号丁运载火箭，成功将株洲太空星际PIESAT-2 13～16星发射升空，卫星顺利进入预定轨道，发射任务取得圆满成功。新华社发（王亚鹏 摄） 新华社太原9月19日电（李国利、李宸）9月19日18时50分，我国在太原卫星发射中心使用长征二号丁运载火箭，成功将株洲太空星际PIESAT-2 13～16星发射升空，卫星顺利进入预定轨道，发射任务取得圆满成功。 这次任务是长征系列运载火箭的第668次飞行。"
