    "content": "新华社南宁9月19日电 题：东博会手记：展馆里的“新面孔”与“老朋友” 新华社记者覃星星、王楚然 南国九月，绿意葱茏。第23届东博会各展馆人流如织、热闹非凡。来自境内外的“新面孔”与“老朋友”在这里碰面，互利共赢的鲜活故事不断上演。 “我真的很开心来到这里，中国有潜力巨大的消费市场，有助于推广我们国家生产的咖啡。”第一次来中国的东帝汶参展商达科斯塔说。 东帝汶展馆占地面积不大，但人气很旺。这是东帝汶自2025年加入东盟后，首次以东盟正式成员国、东博会共办方身份亮相。这也是东盟扩容后11国首次在南宁齐聚，东博会的“朋…"
