    "content": "新华社南宁9月19日电 题：东盟人士期待平陆运河释放区域合作新红利 新华社记者黄耀滕、田子骏、朱丽莉 9月17日，第23届中国—东盟博览会暨中国—东盟商务与投资峰会在广西南宁开幕。本届东博会与峰会恰逢平陆运河建成通航，中国与东盟互联互通再添新通道，东博会专门设置平陆运河展区。与会东盟各界人士如何看待平陆运河通航？记者在会场内外进行了采访。 东盟秘书长高金洪说，平陆运河是一条具有重要历史意义的运河，东盟和中国之间往返的大量货物需要通过港口运输，平陆运河有利于降低中国与东盟综合物流成本，提升区域经济竞争力。东盟和中国是…"
