    "author": "危颖,方亚东,李思远",
    "description": "秭归县作为“中国脐橙之乡”，是湖北省最大的橙子产区。 当地果园依山而种，智能化农用无人机的应用解决了人工采收强度大、风险多、成本高的问题，推动了种植、管护、采收、转运全链条的标准化和现代化。 记者：危颖、方亚东、李思远 摄制：周仕伟 新华社音视频部制作",
    "content": "秭归县作为“中国脐橙之乡”，是湖北省最大的橙子产区。 当地果园依山而种，智能化农用无人机的应用解决了人工采收强度大、风险多、成本高的问题，推动了种植、管护、采收、转运全链条的标准化和现代化。 记者：危颖、方亚东、李思远 摄制：周仕伟 新华社音视频部制作"
