    "title": "中国经济面面观丨城市更新向“下”发力——万亿级“里子工程”打开内需新空间",
    "link": "http://www.news.cn/20260919/7c9a8ff84b2549d48e22d148a47b87f2/c.html",
    "pub_date": "2026-09-19 19:26:28",
    "author": "李海伟,杨有宗",
    "description": "城市地下管网是守护城市运行的“里子工程”，也是筑牢城市安全韧性的核心基建。近期，国务院常务会议部署城市地下管网建设工作。会议指出，地下管网是现代化基础设施网络体系重要组成部分，要以系统思维加快推进建设，从源头消除安全隐患，提高城市功能品质。 为什么在城市高速建设期过后，地下管网反而被提升到如此重要的位置？当管网老化与城市发展需求之间的矛盾日益突出，如何把“看不见”的地下工程变成惠民利民的“里子工程”？ ■老旧病并存，管网短板亟待补齐 作…",
